function sumOfBeauties(nums) {
  const n = nums.length;
  const suffixMin = new Array(n).fill(0);
  suffixMin[n - 1] = nums[n - 1];
  for (let i = n - 2; i >= 0; i--) {
    suffixMin[i] = Math.min(suffixMin[i + 1], nums[i]);
  }

  let prefixMax = nums[0];
  let total = 0;
  for (let i = 1; i <= n - 2; i++) {
    if (prefixMax < nums[i] && nums[i] < suffixMin[i + 1]) {
      total += 2;
    } else if (nums[i - 1] < nums[i] && nums[i] < nums[i + 1]) {
      total += 1;
    }
    prefixMax = Math.max(prefixMax, nums[i]);
  }
  return total;
}

brute:
function sumOfBeauties(nums) {
  let sum = 0;
  for (let i = 1; i < nums.length - 1; i++) {
    let aboveAllLeft = true;
    for (let j = 0; j < i; j++) if (nums[j] >= nums[i]) aboveAllLeft = false;
    let belowAllRight = true;
    for (let k = i + 1; k < nums.length; k++) if (nums[k] <= nums[i]) belowAllRight = false;
    if (aboveAllLeft && belowAllRight) sum += 2;
    else if (nums[i - 1] < nums[i] && nums[i] < nums[i + 1]) sum += 1;
  }
  return sum;
}

