function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 3 + Math.floor(rand() * 10);
  const limit = 100000;
  const mode = Math.floor(rand() * 4);
  if (mode === 0) {
    // Fully random values: mostly beauty 0 and 1.
    const top = size === 'large' ? limit : 1 + Math.floor(rand() * 8);
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
  }
  // A rising trend with occasional dips and repeats, so all three scores appear.
  const nums = [];
  let value = 1 + Math.floor(rand() * 5);
  for (let i = 0; i < n; i++) {
    const roll = rand();
    if (roll < 0.15) value = Math.max(1, value - 1 - Math.floor(rand() * 4));
    else if (roll > 0.25) value += 1 + Math.floor(rand() * (mode === 1 ? 2 : 6));
    nums.push(Math.min(limit, value));
  }
  if (mode === 3) nums.reverse();
  return [nums];
}
